use nucleo::{pattern::{Pattern, CaseMatching, Normalization}, Matcher, Utf32String};

fn main() {
    let mut matcher = Matcher::new(nucleo::Config::DEFAULT);
    let pattern = Pattern::parse("main", CaseMatching::Ignore, Normalization::Smart);
    let mut scratch = Vec::new();
    let s = nucleo::Utf32Str::new("src/main.rs", &mut scratch);
    let score = pattern.score(s, &mut matcher);
    println!("{:?}", score);
}

use git2::Patch;

fn main() {
    let old = b"a\nb\nc\n";
    let new = b"a\nc\nd\n";
    let patch = Patch::from_buffers(old, None, new, None, None).unwrap();
    let num_hunks = patch.num_hunks();
    for i in 0..num_hunks {
        let (hunk, _) = patch.hunk(i).unwrap();
        println!("{} {}", hunk.old_start(), hunk.new_start());
    }
}

use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader};
use std::process::Stdio;

#[tokio::main]
async fn main() {
    let mut child = tokio::process::Command::new("rust-analyzer")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();

    let mut stdin = child.stdin.take().unwrap();
    let mut stdout = BufReader::new(child.stdout.take().unwrap());

    // Initialize
    let msg = r#"{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"processId":null,"rootUri":null,"capabilities":{}}}"#;
    let formatted = format!("Content-Length: {}\r\n\r\n{}", msg.len(), msg);
    stdin.write_all(formatted.as_bytes()).await.unwrap();
    stdin.flush().await.unwrap();

    // Read response
    let mut header = String::new();
    stdout.read_line(&mut header).await.unwrap();
    println!("Header: {:?}", header);
}

