// ── Tool Execution ─────────────────────────────────────────────────

/// Result of a tool execution, shown in the UI.
#[derive(Debug, Clone)]
pub struct ToolExecution {
    pub tool_name: String,
    pub arguments_summary: String,
    pub result_summary: String,
    pub success: bool,
}

async fn execute_tool(name: &str, arguments: &str, cwd: &std::path::Path) -> (String, ToolExecution) {
    let args: serde_json::Value = serde_json::from_str(arguments).unwrap_or(serde_json::Value::Null);

    match name {
        "read_file" => {
            let path_str = args.get("path").and_then(|v| v.as_str()).unwrap_or("");
            let full_path = if std::path::Path::new(path_str).is_absolute() {
                std::path::PathBuf::from(path_str)
            } else {
                cwd.join(path_str)
            };

            match tokio::fs::read_to_string(&full_path).await {
                Ok(content) => {
                    let lines = content.lines().count();
                    let truncated = truncate_str(&content, 15000);
                    let exec = ToolExecution {
                        tool_name: "read_file".into(),
                        arguments_summary: path_str.to_string(),
                        result_summary: format!("✓ Read {} lines", lines),
                        success: true,
                    };
                    (truncated, exec)
                }
                Err(e) => {
                    let exec = ToolExecution {
                        tool_name: "read_file".into(),
                        arguments_summary: path_str.to_string(),
                        result_summary: format!("✗ {}", e),
                        success: false,
                    };
                    (format!("Error: {}", e), exec)
                }
            }
        }
        "write_file" => {
            let path_str = args.get("path").and_then(|v| v.as_str()).unwrap_or("");
            let content = args.get("content").and_then(|v| v.as_str()).unwrap_or("");
            let full_path = if std::path::Path::new(path_str).is_absolute() {
                std::path::PathBuf::from(path_str)
            } else {
                cwd.join(path_str)
            };

            // Create parent directories if needed
            if let Some(parent) = full_path.parent() {
                let _ = tokio::fs::create_dir_all(parent).await;
            }

            match tokio::fs::write(&full_path, content).await {
                Ok(()) => {
                    let lines = content.lines().count();
                    let exec = ToolExecution {
                        tool_name: "write_file".into(),
                        arguments_summary: path_str.to_string(),
                        result_summary: format!("✓ Wrote {} lines", lines),
                        success: true,
                    };
                    (format!("Successfully wrote {} lines to {}", lines, path_str), exec)
                }
                Err(e) => {
                    let exec = ToolExecution {
                        tool_name: "write_file".into(),
                        arguments_summary: path_str.to_string(),
                        result_summary: format!("✗ {}", e),
                        success: false,
                    };
                    (format!("Error: {}", e), exec)
                }
            }
        }
        "run_command" => {
            let cmd = args.get("command").and_then(|v| v.as_str()).unwrap_or("");

            let result = tokio::process::Command::new("bash")
                .arg("-c")
                .arg(cmd)
                .current_dir(cwd)
                .output()
                .await;

            match result {
                Ok(output) => {
                    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
                    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
                    let exit_code = output.status.code().unwrap_or(-1);
                    let combined = if stderr.is_empty() {
                        truncate_str(&stdout, 10000)
                    } else {
                        truncate_str(&format!("{}\nSTDERR:\n{}", stdout, stderr), 10000)
                    };
                    let success = output.status.success();
                    let exec = ToolExecution {
                        tool_name: "run_command".into(),
                        arguments_summary: truncate_str(cmd, 60),
                        result_summary: format!("{} exit code {}", if success { "✓" } else { "✗" }, exit_code),
                        success,
                    };
                    (combined, exec)
                }
                Err(e) => {
                    let exec = ToolExecution {
                        tool_name: "run_command".into(),
                        arguments_summary: truncate_str(cmd, 60),
                        result_summary: format!("✗ {}", e),
                        success: false,
                    };
                    (format!("Error: {}", e), exec)
                }
            }
        }
        "list_directory" => {
            let path_str = args.get("path").and_then(|v| v.as_str()).unwrap_or(".");
            let full_path = if std::path::Path::new(path_str).is_absolute() {
                std::path::PathBuf::from(path_str)
            } else {
                cwd.join(path_str)
            };

            match tokio::fs::read_dir(&full_path).await {
                Ok(mut entries) => {
                    let mut items = Vec::new();
                    while let Ok(Some(entry)) = entries.next_entry().await {
                        let name = entry.file_name().to_string_lossy().to_string();
                        let is_dir = entry.file_type().await.map(|t| t.is_dir()).unwrap_or(false);
                        let marker = if is_dir { "[DIR] " } else { "[FILE]" };
                        items.push(format!("{} {}", marker, name));
                    }
                    items.sort();
                    let result = items.join("\n");
                    let exec = ToolExecution {
                        tool_name: "list_directory".into(),
                        arguments_summary: path_str.to_string(),
                        result_summary: format!("✓ {} entries", items.len()),
                        success: true,
                    };
                    (result, exec)
                }
                Err(e) => {
                    let exec = ToolExecution {
                        tool_name: "list_directory".into(),
                        arguments_summary: path_str.to_string(),
                        result_summary: format!("✗ {}", e),
                        success: false,
                    };
                    (format!("Error: {}", e), exec)
                }
            }
        }
        _ => {
            let exec = ToolExecution {
                tool_name: name.to_string(),
                arguments_summary: String::new(),
                result_summary: "✗ Unknown tool".into(),
                success: false,
            };
            (format!("Unknown tool: {}", name), exec)
        }
    }
}

// ── AI Events (sent to main UI thread) ─────────────────────────────

#[derive(Debug)]
pub enum AiEvent {
    /// A delta text chunk from the streaming response.
    Chunk(String),
    /// A tool is being called (for UI display).
    ToolUse(ToolExecution),
    /// Stream / agent loop finished.
    Done,
    /// An error occurred.
    Error(String),
    /// A file was modified by the agent — UI should refresh.
    FileModified(String),
}

// ── AI State ───────────────────────────────────────────────────────

/// Display-friendly message for the UI (not the raw API messages).
#[derive(Debug, Clone)]
pub enum DisplayMessage {
    User(String),
    Assistant(String),
    ToolUse(ToolExecution),
}

pub struct AiState {
    /// Display messages for the chat UI.
    pub display_messages: Vec<DisplayMessage>,
    /// Full API message history (includes tool calls/results).
    pub api_messages: Vec<ChatMessage>,
    pub input_buffer: String,
    pub input_cursor: usize,
    pub scroll_offset: usize,
    pub is_streaming: bool,
    /// Accumulates the current assistant response while streaming.
    pub streaming_buffer: String,
    /// Animation tick for the streaming indicator.
    pub stream_tick: u8,
}

impl Default for AiState {
    fn default() -> Self {
        Self {
            display_messages: Vec::new(),
            api_messages: Vec::new(),
            input_buffer: String::new(),
            input_cursor: 0,
            scroll_offset: 0,
            is_streaming: false,
            streaming_buffer: String::new(),
            stream_tick: 0,
        }
    }
}

impl AiState {
    /// Extract code blocks from the last assistant message.
    pub fn extract_last_code_block(&self) -> Option<String> {
        for msg in self.display_messages.iter().rev() {
            if let DisplayMessage::Assistant(content) = msg {
                return extract_code_from_markdown(content);
            }
        }
        if !self.streaming_buffer.is_empty() {
            return extract_code_from_markdown(&self.streaming_buffer);
        }
        None
    }
}

/// Extract the last fenced code block from markdown text.
fn extract_code_from_markdown(text: &str) -> Option<String> {
    let mut blocks = Vec::new();
    let mut in_block = false;
    let mut current_block = String::new();

    for line in text.lines() {
        if line.trim_start().starts_with("```") {
            if in_block {
                blocks.push(current_block.clone());
                current_block.clear();
                in_block = false;
            } else {
                in_block = true;
                current_block.clear();
            }
        } else if in_block {
            if !current_block.is_empty() {
                current_block.push('\n');
            }
            current_block.push_str(line);
        }
    }

    blocks.last().cloned()
}

// ── Agent Loop ─────────────────────────────────────────────────────

/// Run the full agentic loop: send message → handle tool calls → repeat → stream final response.
/// This runs in a background tokio task.
pub fn run_agent(
    config: &AiConfig,
    messages: Vec<ChatMessage>,
    cwd: std::path::PathBuf,
    tx: mpsc::Sender<AiEvent>,
) {
    let url = format!("{}/chat/completions", config.base_url.trim_end_matches('/'));
    let api_key = config.api_key.clone();
    let model = config.model.clone();
    let max_tokens = config.max_tokens;
    let tools = get_tool_definitions();

    tokio::spawn(async move {
        let client = match reqwest::Client::builder()
            .timeout(std::time::Duration::from_secs(180))
            .build()
        {
            Ok(c) => c,
            Err(e) => {
                let _ = tx.send(AiEvent::Error(format!("HTTP client error: {}", e)));
                let _ = tx.send(AiEvent::Done);
                return;
            }
        };

        let mut current_messages = messages;
        let max_iterations = 15; // Safety limit for agent loops

        for _iteration in 0..max_iterations {
            // Decide: if this might be the final response, use streaming.
            // For tool-call detection, we first try non-streaming.
            let body = serde_json::json!({
                "model": model,
                "messages": current_messages,
                "max_tokens": max_tokens,
                "tools": tools,
                "stream": false,
            });

            let response = client
                .post(&url)
                .header("Content-Type", "application/json")
                .header("Authorization", format!("Bearer {}", api_key))
                .json(&body)
                .send()
                .await;

            let response = match response {
                Ok(r) => r,
                Err(e) => {
                    let _ = tx.send(AiEvent::Error(format!("Request failed: {}", e)));
                    let _ = tx.send(AiEvent::Done);
                    return;
                }
            };

            if !response.status().is_success() {
                let status = response.status();
                let body_text = response.text().await.unwrap_or_default();
                let _ = tx.send(AiEvent::Error(format!(
                    "API error {}: {}",
                    status,
                    truncate_str(&body_text, 300)
                )));
                let _ = tx.send(AiEvent::Done);
                return;
            }

            let response_body: serde_json::Value = match response.json().await {
                Ok(v) => v,
                Err(e) => {
                    let _ = tx.send(AiEvent::Error(format!("JSON parse error: {}", e)));
                    let _ = tx.send(AiEvent::Done);
                    return;
                }
            };

            let choice = match response_body.get("choices").and_then(|c| c.get(0)) {
                Some(c) => c,
                None => {
                    let _ = tx.send(AiEvent::Error("No choices in response".into()));
                    let _ = tx.send(AiEvent::Done);
                    return;
                }
            };

            let finish_reason = choice.get("finish_reason").and_then(|v| v.as_str()).unwrap_or("");
            let message = match choice.get("message") {
                Some(m) => m,
                None => {
                    let _ = tx.send(AiEvent::Error("No message in choice".into()));
                    let _ = tx.send(AiEvent::Done);
                    return;
                }
            };

            // Check if the model wants to call tools
            if finish_reason == "tool_calls" || message.get("tool_calls").is_some() {
                if let Some(tool_calls) = message.get("tool_calls").and_then(|v| v.as_array()) {
                    // Add the assistant message with tool_calls to history
                    let tc_parsed: Vec<ToolCall> = tool_calls.iter().filter_map(|tc| {
                        Some(ToolCall {
                            id: tc.get("id")?.as_str()?.to_string(),
                            call_type: tc.get("type").and_then(|v| v.as_str()).unwrap_or("function").to_string(),
                            function: FunctionCall {
                                name: tc.get("function")?.get("name")?.as_str()?.to_string(),
                                arguments: tc.get("function")?.get("arguments")?.as_str()?.to_string(),
                            },
                        })
                    }).collect();

                    current_messages.push(ChatMessage::assistant_tool_calls(tc_parsed.clone()));

                    // Execute each tool call
                    for tc in &tc_parsed {
                        let (result, exec) = execute_tool(&tc.function.name, &tc.function.arguments, &cwd).await;

                        // Notify UI about the tool execution
                        let _ = tx.send(AiEvent::ToolUse(exec));

                        // If file was modified, notify UI to refresh
                        if tc.function.name == "write_file" {
                            if let Ok(args) = serde_json::from_str::<serde_json::Value>(&tc.function.arguments) {
                                if let Some(path) = args.get("path").and_then(|v| v.as_str()) {
                                    let _ = tx.send(AiEvent::FileModified(path.to_string()));
                                }
                            }
                        }

                        // Add tool result to messages
                        current_messages.push(ChatMessage::tool_result(&tc.id, &result));
                    }

                    // Continue the loop — the model will process tool results
                    continue;
                }
            }

            // No tool calls — this is the final text response
            if let Some(content) = message.get("content").and_then(|v| v.as_str()) {
                // Send the response as chunks for a streaming-like effect
                let chunk_size = 3; // characters per chunk for typing effect
                let chars: Vec<char> = content.chars().collect();
                for chunk in chars.chunks(chunk_size) {
                    let text: String = chunk.iter().collect();
                    let _ = tx.send(AiEvent::Chunk(text));
                    tokio::time::sleep(std::time::Duration::from_millis(10)).await;
                }
            }

            let _ = tx.send(AiEvent::Done);
            return;
        }

        // If we hit the iteration limit
        let _ = tx.send(AiEvent::Error("Agent reached max iteration limit (15)".into()));
        let _ = tx.send(AiEvent::Done);
    });
}

fn truncate_str(s: &str, max_len: usize) -> String {
    if s.len() <= max_len {
        s.to_string()
    } else {
        format!("{}...", &s[..max_len])
    }
}

use std::io::{Read, Write};
use std::sync::mpsc::Sender;
use portable_pty::{CommandBuilder, NativePtySystem, PtySize, PtySystem};

pub enum PtyCommand {
    Data(Vec<u8>),
    Resize(u16, u16),
}

pub struct Pty {
    pub writer: Box<dyn Write + Send>,
    pub master: Box<dyn portable_pty::MasterPty + Send>,
}

impl Pty {
    pub fn write(&mut self, data: &[u8]) {
        let _ = self.writer.write_all(data);
        let _ = self.writer.flush();
    }

    pub fn resize(&mut self, rows: u16, cols: u16) {
        let _ = self.master.resize(PtySize {
            rows,
            cols,
            pixel_width: 0,
            pixel_height: 0,
        });
    }
}

pub fn spawn_pty(tx: Sender<Vec<u8>>) -> Pty {
    let pty_system = NativePtySystem::default();
    let pair = pty_system.openpty(PtySize {
        rows: 24,
        cols: 80,
        pixel_width: 0,
        pixel_height: 0,
    }).unwrap();

    let cmd = CommandBuilder::new(std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".into()));
    let _child = pair.slave.spawn_command(cmd).unwrap();
    let mut reader = pair.master.try_clone_reader().unwrap();
    let writer = pair.master.take_writer().unwrap();

    std::thread::spawn(move || {
        let mut buf = [0u8; 1024];
        while let Ok(n) = reader.read(&mut buf) {
            if n == 0 { break; }
            if tx.send(buf[..n].to_vec()).is_err() {
                break;
            }
        }
    });

    Pty { writer, master: pair.master }
}

pub mod pty;

use ratatui::style::{Color, Modifier, Style};
use vte::{Params, Perform};

#[derive(Clone, Debug)]
pub struct TermCell {
    pub char: char,
    pub style: Style,
}

pub struct TerminalState {
    pub lines: Vec<Vec<TermCell>>,
    pub cursor_x: usize,
    pub cursor_y: usize, // Absolute row in lines
    pub screen_base: usize, // First visible row in lines
    pub width: usize,
    pub height: usize,
    pub current_style: Style,
    pub scroll_offset: usize, // User scroll offset from bottom
}

impl TerminalState {
    pub fn new(width: usize, height: usize) -> Self {
        Self {
            lines: vec![Vec::new()],
            cursor_x: 0,
            cursor_y: 0,
            screen_base: 0,
            width,
            height,
            current_style: Style::default(),
            scroll_offset: 0,
        }
    }

    pub fn resize(&mut self, width: usize, height: usize) {
        self.width = width;
        self.height = height;
    }
}

impl Perform for TerminalState {
    fn print(&mut self, c: char) {
        let y = self.cursor_y;
        if y >= self.lines.len() {
            self.lines.resize(y + 1, Vec::new());
        }
        let line = &mut self.lines[y];
        if self.cursor_x >= line.len() {
            line.resize(self.cursor_x + 1, TermCell { char: ' ', style: self.current_style });
        }
        line[self.cursor_x] = TermCell { char: c, style: self.current_style };
        self.cursor_x += 1;
        if self.cursor_x >= self.width {
            self.cursor_x = 0;
            self.cursor_y += 1;
            if self.cursor_y >= self.screen_base + self.height {
                self.screen_base = self.cursor_y - self.height + 1;
            }
        }
    }

    fn execute(&mut self, byte: u8) {
        match byte {
            b'\n' => {
                self.cursor_y += 1;
                if self.cursor_y >= self.screen_base + self.height {
                    self.screen_base = self.cursor_y - self.height + 1;
                }
            }
            b'\r' => self.cursor_x = 0,
            b'\t' => {
                let next_tab = (self.cursor_x / 8 + 1) * 8;
                self.cursor_x = next_tab.min(self.width.saturating_sub(1));
            }
            b'\x08' => self.cursor_x = self.cursor_x.saturating_sub(1), // Backspace
            _ => {}
        }
    }

    fn csi_dispatch(&mut self, params: &Params, _intermediates: &[u8], _ignore: bool, action: char) {
        match action {
            'm' => { // SGR (Select Graphic Rendition)
                if params.is_empty() {
                    self.current_style = Style::default();
                    return;
                }
                for param in params {
                    let mut iter = param.iter();
                    while let Some(&code) = iter.next() {
                        match code {
                            0 => self.current_style = Style::default(),
                            1 => self.current_style = self.current_style.add_modifier(Modifier::BOLD),
                            30..=37 => {
                                let colors = [Color::Black, Color::Red, Color::Green, Color::Yellow, Color::Blue, Color::Magenta, Color::Cyan, Color::Gray];
                                self.current_style = self.current_style.fg(colors[(code - 30) as usize]);
                            }
                            39 => self.current_style.fg = None,
                            40..=47 => {
                                let colors = [Color::Black, Color::Red, Color::Green, Color::Yellow, Color::Blue, Color::Magenta, Color::Cyan, Color::Gray];
                                self.current_style = self.current_style.bg(colors[(code - 40) as usize]);
                            }
                            49 => self.current_style.bg = None,
                            90..=97 => { // Bright fg
                                let colors = [Color::DarkGray, Color::LightRed, Color::LightGreen, Color::LightYellow, Color::LightBlue, Color::LightMagenta, Color::LightCyan, Color::White];
                                self.current_style = self.current_style.fg(colors[(code - 90) as usize]);
                            }
                            100..=107 => { // Bright bg
                                let colors = [Color::DarkGray, Color::LightRed, Color::LightGreen, Color::LightYellow, Color::LightBlue, Color::LightMagenta, Color::LightCyan, Color::White];
                                self.current_style = self.current_style.bg(colors[(code - 100) as usize]);
                            }
                            _ => {}
                        }
                    }
                }
            }
            'A' => { // Cursor Up
                let n = params.iter().next().and_then(|p| p.iter().next().copied()).unwrap_or(1) as usize;
                self.cursor_y = self.cursor_y.saturating_sub(n).max(self.screen_base);
            }
            'B' => { // Cursor Down
                let n = params.iter().next().and_then(|p| p.iter().next().copied()).unwrap_or(1) as usize;
                self.cursor_y = (self.cursor_y + n).min(self.screen_base + self.height - 1);
            }
            'C' => { // Cursor Forward
                let n = params.iter().next().and_then(|p| p.iter().next().copied()).unwrap_or(1) as usize;
                self.cursor_x += n;
            }
            'D' => { // Cursor Back
                let n = params.iter().next().and_then(|p| p.iter().next().copied()).unwrap_or(1) as usize;
                self.cursor_x = self.cursor_x.saturating_sub(n);
            }
            'K' => { // Erase in Line
                let mode = params.iter().next().and_then(|p| p.iter().next().copied()).unwrap_or(0);
                if self.cursor_y >= self.lines.len() {
                    self.lines.resize(self.cursor_y + 1, Vec::new());
                }
                if mode == 0 {
                    self.lines[self.cursor_y].truncate(self.cursor_x);
                } else if mode == 2 {
                    self.lines[self.cursor_y].clear();
                }
            }
            'J' => { // Erase in Display
                let mode = params.iter().next().and_then(|p| p.iter().next().copied()).unwrap_or(0);
                if mode == 2 { // Clear entire screen
                    for i in 0..self.height {
                        let y = self.screen_base + i;
                        if y < self.lines.len() {
                            self.lines[y].clear();
                        }
                    }
                    self.cursor_y = self.screen_base;
                    self.cursor_x = 0;
                }
            }
            'H' | 'f' => { // Cursor Position
                let mut it = params.iter();
                let row = it.next().and_then(|p| p.iter().next().copied()).unwrap_or(1) as usize;
                let col = it.next().and_then(|p| p.iter().next().copied()).unwrap_or(1) as usize;
                self.cursor_y = self.screen_base + row.saturating_sub(1);
                self.cursor_x = col.saturating_sub(1);
            }
            'L' => { // Insert Line
                let n = params.iter().next().and_then(|p| p.iter().next().copied()).unwrap_or(1) as usize;
                for _ in 0..n {
                    if self.cursor_y < self.lines.len() {
                        self.lines.insert(self.cursor_y, Vec::new());
                    }
                }
            }
            'M' => { // Delete Line
                let n = params.iter().next().and_then(|p| p.iter().next().copied()).unwrap_or(1) as usize;
                for _ in 0..n {
                    if self.cursor_y < self.lines.len() {
                        self.lines.remove(self.cursor_y);
                    }
                }
            }
            _ => {}
        }
    }
}

use lsp_types::*;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::process::Stdio;
use std::str::FromStr;
use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader};
// Removed unused ChildStdin
use tokio::sync::mpsc::{self, Receiver, Sender};

#[derive(Debug, Serialize, Deserialize)]
pub struct JsonRpcRequest {
    pub jsonrpc: String,
    pub id: i64,
    pub method: String,
    pub params: Value,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct JsonRpcNotification {
    pub jsonrpc: String,
    pub method: String,
    pub params: Value,
}

#[derive(Debug)]
pub enum LspMessage {
    Notification(String, Value),
    Response(i64, Value),
    Error(i64, Value),
}

pub struct LspClient {
    req_tx: Sender<String>,
    next_id: i64,
}

impl LspClient {
    pub fn new() -> (Self, Receiver<LspMessage>) {
        let mut child = tokio::process::Command::new("rust-analyzer")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .expect("Failed to start rust-analyzer. Ensure it is in your PATH.");

        let mut stdin = child.stdin.take().unwrap();
        let mut stdout = BufReader::new(child.stdout.take().unwrap());

        let (msg_tx, msg_rx) = mpsc::channel(100);
        let (req_tx, mut req_rx) = mpsc::channel::<String>(100);

        // Reader task
        tokio::spawn(async move {
            loop {
                let mut header = String::new();
                if stdout.read_line(&mut header).await.unwrap_or(0usize) == 0 {
                    break;
                }

                let mut content_length = 0;
                if header.starts_with("Content-Length: ") {
                    content_length = header["Content-Length: ".len()..].trim().parse().unwrap_or(0);
                }

                // Read headers until empty line
                loop {
                    let mut line = String::new();
                    let _ = stdout.read_line(&mut line).await.unwrap_or(0usize);
                    if line.trim().is_empty() {
                        break;
                    }
                    if line.starts_with("Content-Length: ") {
                        content_length = line["Content-Length: ".len()..].trim().parse().unwrap_or(0);
                    }
                }

                if content_length > 0 {
                    let mut buf = vec![0; content_length];
                    if stdout.read_exact(&mut buf).await.is_err() {
                        break;
                    }
                    if let Ok(payload) = serde_json::from_slice::<Value>(&buf) {

                        if payload.get("id").is_some() && payload.get("method").is_some() {
                            // Request from server, typically ignore for MVP
                        } else if payload.get("id").is_some() {
                            let id = payload["id"].as_i64().unwrap_or(0);
                            if let Some(err) = payload.get("error") {
                                let _ = msg_tx.send(LspMessage::Error(id, err.clone())).await;
                            } else if let Some(res) = payload.get("result") {
                                let _ = msg_tx.send(LspMessage::Response(id, res.clone())).await;
                            }
                        } else if payload.get("method").is_some() {
                            let method = payload["method"].as_str().unwrap().to_string();
                            let params = payload.get("params").cloned().unwrap_or(Value::Null);
                            let _ = msg_tx.send(LspMessage::Notification(method, params)).await;
                        }
                    }
                }
            }
        });

        // Writer task
        tokio::spawn(async move {
            while let Some(msg) = req_rx.recv().await {
                let formatted = format!("Content-Length: {}\r\n\r\n{}", msg.len(), msg);
                if stdin.write_all(formatted.as_bytes()).await.is_err() {
                    break;
                }
                let _ = stdin.flush().await;
            }
        });

        (Self { req_tx, next_id: 1 }, msg_rx)
    }

    pub fn send_request(&mut self, method: &str, params: Value) -> i64 {
        let id = self.next_id;
        self.next_id += 1;
        let req = JsonRpcRequest {
            jsonrpc: "2.0".to_string(),
            id,
            method: method.to_string(),
            params,
        };
        let msg = serde_json::to_string(&req).unwrap();
        let tx = self.req_tx.clone();
        tokio::spawn(async move {
            let _ = tx.send(msg).await;
        });
        id
    }

    pub fn send_notification(&self, method: &str, params: Value) {
        let notif = JsonRpcNotification {
            jsonrpc: "2.0".to_string(),
            method: method.to_string(),
            params,
        };
        let msg = serde_json::to_string(&notif).unwrap();
        let tx = self.req_tx.clone();
        tokio::spawn(async move {
            let _ = tx.send(msg).await;
        });
    }

    pub fn initialize(&mut self, root_url: url::Url) -> i64 {
        let root_uri = lsp_types::Uri::from_str(&root_url.to_string()).unwrap();
        #[allow(deprecated)]
        let params = InitializeParams {
            process_id: Some(std::process::id()),
            root_uri: Some(root_uri.clone()),
            workspace_folders: Some(vec![WorkspaceFolder {
                uri: root_uri,
                name: "root".to_string(),
            }]),
            capabilities: ClientCapabilities::default(),
            ..Default::default()
        };
        self.send_request("initialize", serde_json::to_value(params).unwrap())
    }

    pub fn initialized(&self) {
        self.send_notification("initialized", serde_json::json!({}));
    }

    pub fn did_open(&self, url: url::Url, text: String, version: i32) {
        let uri = lsp_types::Uri::from_str(&url.to_string()).unwrap();
        let params = DidOpenTextDocumentParams {
            text_document: TextDocumentItem {
                uri,
                language_id: "rust".to_string(), // MVP hardcoded
                version,
                text,
            },
        };
        self.send_notification("textDocument/didOpen", serde_json::to_value(params).unwrap());
    }

    pub fn did_change(&self, url: url::Url, text: String, version: i32) {
        let uri = lsp_types::Uri::from_str(&url.to_string()).unwrap();
        let params = DidChangeTextDocumentParams {
            text_document: VersionedTextDocumentIdentifier { uri, version },
            content_changes: vec![TextDocumentContentChangeEvent {
                range: None,
                range_length: None,
                text,
            }],
        };
        self.send_notification("textDocument/didChange", serde_json::to_value(params).unwrap());
    }

    pub fn completion(&mut self, url: url::Url, line: u32, character: u32) -> i64 {
        let uri = lsp_types::Uri::from_str(&url.to_string()).unwrap();
        let params = CompletionParams {
            text_document_position: TextDocumentPositionParams {
                text_document: TextDocumentIdentifier { uri },
                position: Position { line, character },
            },
            work_done_progress_params: Default::default(),
            partial_result_params: Default::default(),
            context: None,
        };
        self.send_request("textDocument/completion", serde_json::to_value(params).unwrap())
    }

    pub fn definition(&mut self, uri: lsp_types::Uri, line: u32, character: u32) -> i64 {
        let params = GotoDefinitionParams {
            text_document_position_params: TextDocumentPositionParams {
                text_document: TextDocumentIdentifier { uri },
                position: Position { line, character },
            },
            work_done_progress_params: WorkDoneProgressParams::default(),
            partial_result_params: PartialResultParams::default(),
        };
        self.send_request("textDocument/definition", serde_json::to_value(params).unwrap())
    }
}
